    procedure: 'From nest/ run `node scripts/validate-pipeline-contracts.cjs` and confirm no `no-stale-scoring` failure. Then open `/status/health-check` and read the **Feed Freshness** section — it lists every symbol whose newest bar is outside its cadence tolerance, and distinguishes "No bars at all" from "Feed stopped". Finally, pick a ticker from that list and call `GET /api/signals/envelope/<ticker>?protocol=<slug>`: the response must carry a pre-trade blocker naming #827 and no `directiveoutcome` row may appear for it.',
    expected: 'No `no-stale-scoring` failure — exactly ONE call site of `recordOutcomes()` exists in `nest/src/modules`, it is in `signal-envelope.service.ts`, and `everyCadenceStale()` appears BEFORE it in that file. The Feed Freshness section lists the starved symbols with symbol, newest-bar timestamp, age and missing timeframes; an EMPTY list renders as a green confirmation ("All N scored symbols have bars inside their cadence tolerance") and a FAILED query renders as a critical notice reading "This is NOT an all-clear" — the two must never look the same. Envelope calls for a starved ticker return the stale blocker rather than a plausible score. ⚠️ The regression this catches is the BASE-CADENCE-ONLY variant: gating on the base cadence alone skipped 11 symbols that were fresh on 5–6 other timeframes (SPY `1m`=12h stale but `5m`=0.1h fresh), silently reclassifying healthy symbols as dead.',
